#!/usr/bin/env bash
# Run source-identical ordinary-native, native-MPS, and smolvm GRPO arms.
set -euo pipefail

BENCH_DIR="$(cd "$(dirname "$0")" && pwd)"
if [[ -f "$BENCH_DIR/.grpo-repro.env" ]]; then
    # Contains only local paths generated by setup_grpo_repro.sh.
    source "$BENCH_DIR/.grpo-repro.env"
fi
MODE="${1:---full}"
case "$MODE" in
    --smoke)
        N="${N:-1}"; STEPS="${STEPS:-5}"; GRPO_WARM_STEPS="${GRPO_WARM_STEPS:-1}"
        ;;
    --full)
        N="${N:-8}"; STEPS="${STEPS:-200}"; GRPO_WARM_STEPS="${GRPO_WARM_STEPS:-20}"
        ;;
    *)
        echo "usage: $0 [--smoke|--full]" >&2
        exit 2
        ;;
esac

CPUS="${CPUS:-2}"
BATCH="${BATCH:-1}"
MAXSEQ="${MAXSEQ:-256}"
TIMEOUT="${TIMEOUT:-1800}"
RUN_CONTROL="${RUN_CONTROL:-1}"
RUN_TAG="${RUN_TAG:-groundzero-$(date +%Y%m%d-%H%M%S)}"
SMOLVM="${SMOLVM:-$HOME/smolvm/smolvm}"
PY_VENV="${PY_VENV:-$HOME/ptwork/bin/python}"
PACK="${PACK:-$HOME/qlora-baked.smolmachine}"

for path in "$SMOLVM" "$PY_VENV" "$PACK"; do
    [[ -e "$path" ]] || { echo "missing prerequisite: $path" >&2; exit 1; }
done
for command_name in bc nvidia-cuda-mps-control nvidia-smi python3; do
    command -v "$command_name" >/dev/null 2>&1 || {
        echo "missing required command: $command_name" >&2
        exit 1
    }
done

export SMOLVM PY_VENV PACK GRPO_WARM_STEPS
export N STEPS CPUS BATCH MAXSEQ TIMEOUT RUN_CONTROL RUN_TAG
"$BENCH_DIR/run_native_mps_matrix.sh"

"$BENCH_DIR/bench.sh" --arm fork --n "$N" --steps "$STEPS" --cpus "$CPUS" \
    --vcpu "$CPUS" --batch "$BATCH" --maxseq "$MAXSEQ" --timeout "$TIMEOUT" \
    --workload workload_grpo.py --share on --tag "grpo-fork-$RUN_TAG"

native_result=$(find "$BENCH_DIR/results" -maxdepth 1 -type f \
    -name "native_grpo-native-mps-${RUN_TAG}_*.json" -print | sort | tail -1)
fork_result=$(find "$BENCH_DIR/results" -maxdepth 1 -type f \
    -name "fork_grpo-fork-${RUN_TAG}_*.json" -print | sort | tail -1)
[[ -n "$native_result" && -n "$fork_result" ]] || {
    echo "could not locate paired results for $RUN_TAG" >&2
    exit 1
}

comparison="$BENCH_DIR/results/compare_grpo-${RUN_TAG}.json"
if [[ "$MODE" == "--full" ]]; then
    "$BENCH_DIR/compare_grpo.py" "$native_result" "$fork_result" | tee "$comparison"
else
    echo "Smoke run completed; the 200-step full run is required for stochastic quality gates."
fi

echo "native MPS: $native_result"
echo "smolvm fork: $fork_result"
[[ -f "$comparison" ]] && echo "comparison:  $comparison"
